er:1px solid var(--line);border-left:4px solid var(--blue);border-radius:8px;padding:7px;background:var(--soft);font-size:11px}.match.is-called{border-color:var(--gold);border-left-color:var(--gold);background:#fff5c7;box-shadow:0 0 0 2px rgba(228,169,0,.2)}.match.is-in-progress{border-color:var(--green);border-left-color:var(--green);background:#dff7ea;box-shadow:0 0 0 2px rgba(7,132,77,.2)}.table-active{display:inline-flex;margin-top:5px;padding:3px 7px;border-radius:999px;background:var(--gold);color:#17253a;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.04em}.match.is-in-progress .table-active{background:var(--green);color:#fff}.match b{display:block;margin-bottom:5px;color:var(--navy)}.line{display:flex;justify-content:space-between;gap:8px;padding:3px 0}.winner{color:var(--green);font-weight:900}.standings{width:100%;border-collapse:collapse;font-size:11px}.standings th{background:var(--green);color:#fff}.standings th,.standings td{padding:7px;border:1px solid var(--line);text-align:center}.standings td:nth-child(2){text-align:left;font-weight:800}.scroll{overflow:auto}.bracket{display:grid;gap:13px;min-width:920px}.round{display:flex;flex-direction:column;justify-content:space-around;gap:9px}.round h3{text-align:center;margin:0 0 7px;padding:7px;background:var(--navy);color:#fff;border-radius:7px;font-size:11px}.empty{padding:35px;text-align:center;border:1px dashed var(--line);border-radius:12px;background:var(--surface)}.error{color:#b42318}footer{margin-top:24px;padding:14px 0;border-top:2px solid var(--navy);display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:11px}@media(prefers-color-scheme:dark){:root{--ink:#eef4ff;--muted:#9dadc2;--line:#2b3950;--surface:#111a28;--soft:#182334;--page:#09111d}.match.is-called{background:#3b3215;color:#fff4c2}.match.is-in-progress{background:#11392a;color:#e5fff2}}@media(max-width:760px){.zone-body{grid-template-columns:1fr}.matches{grid-template-columns:1fr}.phase-head,footer{align-items:flex-start;flex-direction:column}.standings{min-width:580px}}
        .zone-bracket-scroll{overflow:auto}.zone-bracket{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));grid-template-rows:repeat(3,minmax(78px,auto));gap:7px 16px;min-width:570px;align-items:center}.zone-bracket .match{position:relative;font-size:10px;padding:5px}.zone-bracket .line{padding:2px 0;line-height:1.15}.zone-bracket .match b{margin-bottom:3px}.zone-bracket .z-m1{grid-column:1;grid-row:1}.zone-bracket .z-m2{grid-column:1;grid-row:2}.zone-bracket .z-loss{grid-column:1;grid-row:3}.zone-bracket .z-win{grid-column:2;grid-row:1}.zone-bracket .z-second{grid-column:2;grid-row:3}.zone-bracket .z-first{grid-column:3;grid-row:1}.zone-bracket .z-runner{grid-column:3;grid-row:3}.zone-bracket .z-win:after,.zone-bracket .z-second:after{content:"";position:absolute;top:50%;right:-16px;width:16px;border-top:1px solid var(--line)}.place{border:2px solid var(--navy);border-radius:6px;background:var(--surface);padding:5px;text-align:center;font-size:10px}.place b{display:block;color:var(--navy);text-transform:uppercase}.place span{display:block;margin-top:3px;font-weight:900}.set-points{display:flex;gap:2px;margin-left:auto}.set-point{display:inline-grid;place-items:center;min-width:21px;height:19px;padding:0 2px;border:1px solid var(--line);background:var(--surface);font-weight:900}.set-point.is-set-winner{border-color:#07844d;background:#dff7ea;color:#067647}.dark .set-point.is-set-winner{background:#11392a;color:#5aeda7}
