        .crossing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,330px));gap:12px;justify-content:start}.crossing-card{min-width:0;padding:10px 11px;font-size:12px}.crossing-winner{display:flex;align-items:center;gap:7px;margin-top:8px;padding-top:8px;border-top:1px solid var(--line);color:var(--green);font-weight:900}.crossing-winner svg{width:17px;height:17px;flex:none}.crossing-pending{color:var(--muted)}@media(max-width:560px){.crossing-grid{grid-template-columns:1fr}.crossing-card{width:100%}}
