<dialog class="qualified-modal" id="qualified-modal"><div class="qualified-modal-head"><h3 id="qualified-title">Clasificados</h3><div class="qualified-modal-actions"><button type="button" title="Compartir" aria-label="Compartir clasificados" onclick="shareQualified()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.6 6.8-4.2M8.6 13.4l6.8 4.2"/></svg></button><button type="button" title="Imprimir" aria-label="Imprimir clasificados" onclick="printQualified()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 8V3h10v5M7 17h10v4H7z"/><path d="M6 17H4V9h16v8h-2M16 12h1"/></svg></button><button class="qualified-close" type="button" onclick="document.querySelector('#qualified-modal').close()" aria-label="Cerrar">×</button></div></div><div class="qualified-modal-body" id="qualified-body"></div></dialog>
<script>
const endpoint=@json($jsonUrl),pdfBase=@json($pdfBaseUrl);let data=null;
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const stateLabel=s=>({pending:'Pendiente',ready:'Preparada',in_progress:'En curso',completed:'Finalizada'}[s]||s);
function sectionActions(title,key,phase=null){const url=`${pdfBase}/${key}/pdf`,encoded=encodeURIComponent(title),qualified=phase&&Array.isArray(phase.clasificados)&&phase.clasificados.length?`<button class="icon-action qualified-action" type="button" onclick="showQualified(${Number(phase.id)})">Clasificados <span>${phase.clasificados.length}</span></button>`:'';return `<div class="section-actions">${qualified}<button class="icon-action" type="button" title="Compartir" aria-label="Compartir ${esc(title)}" onclick="shareSection('${encoded}','${url}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.6 6.8-4.2M8.6 13.4l6.8 4.2"/></svg></button><a class="icon-action" href="${url}" target="_blank" title="Exportar PDF" aria-label="Exportar ${esc(title)} a PDF"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M6 2h9l5 5v15H6z"/><path d="M14 2v6h6M9 15h6M9 18h6"/></svg></a></div>`}
function showQualified(phaseId){const phase=data.fases.find(p=>Number(p.id)===Number(phaseId)),rows=phase?.clasificados||[],method=rows[0]?.classification_method||'manual',modal=document.querySelector('#qualified-modal');let extraHead='',extraCells=()=>'';if(method==='previous_results'){extraHead='<th>Pos. zona</th><th>DS</th><th>Promedio</th>';extraCells=r=>`<td>${esc(r.zone_position||'—')}</td><td>${esc(r.sets_difference??'—')}</td><td>${esc(r.average===null||r.average===undefined?'—':Number(r.average).toFixed(3))}</td>`}else if(method==='national_ranking'){extraHead='<th>Ranking</th>';extraCells=r=>`<td>${esc(r.ranking||'Sin ranking')}</td>`}else if(method==='number_draw'||method==='automatic_draw'){extraHead='<th>N.º sorteo</th>';extraCells=r=>`<td>${esc(r.draw_number||'—')}</td>`}const title=`Clasificados de ${phase?.nombre||'la fase'}`;document.querySelector('#qualified-title').textContent=title;modal.dataset.shareTitle=`${data.torneo} · ${title}`;document.querySelector('#qualified-body').innerHTML=rows.length?`<div class="scroll"><table class="standings"><thead><tr><th>Posición</th><th>Jugador</th><th>Club</th>${extraHead}<th>Próxima fase</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.position)}</td><td>${esc(r.player)}</td><td>${esc(r.club||'—')}</td>${extraCells(r)}<td>${esc(r.next_phase)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Todavía no hay jugadores clasificados.</div>';modal.showModal()}
async function shareQualified(){const modal=document.querySelector('#qualified-modal'),title=modal.dataset.shareTitle||'Clasificados',text=`${title}\n\n${modal.querySelector('table')?.innerText||''}`;if(navigator.share)return navigator.share({title,text,url:window.location.href});await navigator.clipboard.writeText(`${text}\n${window.location.href}`);alert('La lista de clasificados fue copiada para compartir.')}
function printQualified(){const modal=document.querySelector('#qualified-modal'),sourceTable=modal.querySelector('table');if(!sourceTable)return;const title=modal.dataset.shareTitle||'Clasificados',popup=window.open('','_blank','width=1100,height=800'),style=popup.document.createElement('style');style.textContent='@page{size:landscape;margin:12mm 14mm}.print-layout{width:100%;border-collapse:collapse}.print-layout>thead{display:table-header-group}.print-layout>tfoot{display:table-footer-group}.print-layout>thead>tr>td{padding:0 0 7mm;border:0}.print-layout>tfoot>tr>td{padding:7mm 0 0;border:0}.print-layout>tbody>tr>td{padding:0;border:0;vertical-align:top}body{font-family:Arial,sans-serif;margin:0;color:#17253a}.print-header{border-bottom:2px solid #173d7c;padding-bottom:7px}.print-header h1{margin:7px 0 0;font-size:18px}.tournament-info{display:grid;grid-template-columns:auto repeat(5,minmax(0,1fr));gap:10px;align-items:center;margin:0;padding:0;border:0}.tournament-info img{width:44px;height:44px;object-fit:contain}.info small{display:block;color:#65758b;font-size:8px;text-transform:uppercase}.info strong{display:block;margin-top:2px;font-size:10px}.print-footer{display:flex;justify-content:space-between;padding-top:7px;border-top:2px solid #173d7c;color:#65758b;font-size:9px}.print-content{width:100%}.print-content table{width:100%;border-collapse:collapse;font-size:11px}.print-content thead{display:table-header-group}.print-content th,.print-content td{padding:7px;border:1px solid #b8c3d1;text-align:left}.print-content th{background:#173d7c!important;color:#fff!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}.print-content tr{break-inside:avoid}';const header=popup.document.createElement('header');header.className='print-header';const sourceInfo=document.querySelector('.tournament-info');if(sourceInfo)header.appendChild(sourceInfo.cloneNode(true));const heading=popup.document.createElement('h1');heading.textContent=title;header.appendChild(heading);const content=popup.document.createElement('main');content.className='print-content';content.appendChild(sourceTable.cloneNode(true));const footer=popup.document.createElement('footer');footer.className='print-footer';const federation=popup.document.createElement('strong');federation.textContent='Federación Argentina de Billar';const official=popup.document.createElement('span');official.textContent='Información oficial del torneo';footer.append(federation,official);const layout=popup.document.createElement('table');layout.className='print-layout';layout.createTHead().insertRow().insertCell().appendChild(header);layout.createTFoot().insertRow().insertCell().appendChild(footer);layout.createTBody().insertRow().insertCell().appendChild(content);popup.document.title=title;popup.document.head.appendChild(style);popup.document.body.appendChild(layout);popup.focus();setTimeout(()=>{popup.print();popup.close()},350)}
async function shareSection(encoded,url){const title=decodeURIComponent(encoded),payload={title:`${data.torneo} · ${title}`,text:`${data.torneo}\n${title}`,url};if(navigator.share)return navigator.share(payload);await navigator.clipboard.writeText(url);alert('El enlace al PDF fue copiado para compartir.')}
function score(m,i){return Array.isArray(m.sets_computables)?m.sets_computables[i]:'—'}
function activeMatchClass(m){return m.estado==='called'?' is-called':(m.estado==='in_progress'?' is-in-progress':'')}
function tableStatus(m){if(!m.mesa)return '';if(m.estado==='called'||m.estado==='in_progress')return `<small class="table-active">Mesa ${esc(m.mesa)}</small>`;return `<small>Mesa ${esc(m.mesa)}</small>`}
function matchMeta(m){return `<div class="match-meta">${m.horario?`<small>${esc(m.horario)}</small>`:''}${tableStatus(m)}</div>`}
function matchCard(m){return `<article class="match${activeMatchClass(m)}"><div class="line ${m.ganador===m.jugador_1?'winner':''}"><span><strong>${esc(m.numero_1)}</strong> · ${esc(m.jugador_1||m.placeholder_1||'A designar')}</span>${setPoints(m,'player_one_points')}</div><div class="line ${m.ganador===m.jugador_2?'winner':''}"><span><strong>${esc(m.numero_2)}</strong> · ${esc(m.jugador_2||m.placeholder_2||'A designar')}</span>${setPoints(m,'player_two_points')}</div>${matchMeta(m)}</article>`}
function zoneClass(m){return {'Partido 1':'z-m1','Partido 2':'z-m2','Definición del primer puesto':'z-win','Perdedores':'z-loss','Partido de recuperación':'z-loss','Definición del segundo puesto':'z-second'}[m.etiqueta]||''}
function setPoints(m,key){const sets=Array.isArray(m.sets?.sets)?m.sets.sets:[],target=Number(m.puntos_por_set||0);return `<span class="set-points">${sets.length?sets.map(s=>{const value=s[key];return `<span class="set-point${target>0&&Number(value)===target?' is-set-winner':''}">${esc(value)}</span>`}).join(''):'<span class="set-point">—</span>'}</span>`}
function zoneMatchCard(m){const label=m.etiqueta==='Partido de recuperación'?'Perdedores':m.etiqueta;return `<article class="match ${zoneClass(m)}${activeMatchClass(m)}"><b>${esc(label)}</b><div class="line ${m.ganador===m.jugador_1?'winner':''}"><span>${esc(m.jugador_1)}</span>${setPoints(m,'player_one_points')}</div><div class="line ${m.ganador===m.jugador_2?'winner':''}"><span>${esc(m.jugador_2)}</span>${setPoints(m,'player_two_points')}</div>${matchMeta(m)}</article>`}
function zones(phase){const slots=[...new Set(phase.zonas.map(z=>z.horario||'SIN HORARIO'))];const nav=slots.map((s,i)=>`<button class="slot ${i?'':'on'}" data-slot="${esc(s)}">${esc(s)}</button>`).join('');return `<div class="slots">${nav}</div><div class="zones" id="zones">${zoneCards(phase,slots[0])}</div>`}
function zoneCards(phase,slot){return phase.zonas.filter(z=>(z.horario||'SIN HORARIO')===slot).map(z=>{const ms=phase.partidos.filter(m=>m.zona_id===z.id),first=ms.find(m=>m.etiqueta==='Definición del primer puesto'&&m.estado==='completed')?.ganador||'A definir',second=ms.find(m=>m.etiqueta==='Definición del segundo puesto'&&m.estado==='completed')?.ganador||'A definir';return `<section class="zone"><div class="zone-title"><span>${esc(z.nombre)}</span><span>${esc(z.horario)}</span></div><div class="zone-body"><div class="zone-bracket-scroll"><div class="zone-bracket">${ms.map(zoneMatchCard).join('')}<div class="place z-first"><b>1° puesto</b><span>${esc(first)}</span></div><div class="place z-runner"><b>2.º puesto</b><span>${esc(second)}</span></div></div></div><div class="scroll"><table class="standings"><thead><tr><th>Pos</th><th>Jugador</th><th>PG</th><th>DS</th><th>PF</th><th>PC</th><th>Prom</th></tr></thead><tbody>${z.jugadores.slice().sort((a,b)=>(a.clasificacion||99)-(b.clasificacion||99)).map(p=>`<tr><td>${esc(p.clasificacion)}</td><td>${esc(p.nombre)}</td><td>${esc(p.partidos_ganados)}</td><td>${esc(p.diferencia_sets)}</td><td>${esc(p.puntos_favor)}</td><td>${esc(p.puntos_contra)}</td><td>${esc(p.promedio)}</td></tr>`).join('')}</tbody></table></div></div></section>`}).join('')||'<div class="empty">Todavía no hay zonas publicadas para este horario.</div>'}
function qualifiedCard(m){return `<article class="match"><small class="qualified-label">Clasificado</small><div class="line ${m.ganador?'winner':''}"><span><strong>${esc(m.ganador?(m.ganador===m.jugador_1?m.numero_1:m.numero_2):'—')}</strong> · ${esc(m.ganador||'A definir')}</span>${m.ganador?'🏆':''}</div><small class="qualified-note">Vencedor de la ${esc(m.ronda)}.ª ronda</small></article>`}
function bracketGrid(matches,qualifiers=1){const rounds=matches.reduce((a,m)=>((a[m.ronda]??=[]).push(m),a),{}),keys=Object.keys(rounds).sort((a,b)=>a-b),last=keys.length?rounds[keys[keys.length-1]].slice().sort((a,b)=>a.orden-b.orden):[],showQualified=Number(qualifiers)>1&&last.length>0,total=keys.length+(showQualified?1:0);return `<div class="scroll"><div class="bracket" style="grid-template-columns:repeat(${Math.max(total,1)},minmax(190px,1fr))">${keys.map(k=>`<section class="round">${rounds[k].sort((a,b)=>a.orden-b.orden).map(matchCard).join('')}</section>`).join('')}${showQualified?`<section class="round qualified-round">${last.map(qualifiedCard).join('')}</section>`:''}</div></div>`}
function crossingCard(m){const winner=m.ganador?`<div class="crossing-winner"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M8 4h8v5a4 4 0 0 1-8 0zM8 6H4v1a4 4 0 0 0 4 4m8-5h4v1a4 4 0 0 1-4 4M12 13v4m-4 3h8"/></svg><span>Ganador: ${esc(m.ganador)}</span></div>`:`<div class="crossing-winner crossing-pending">Ganador a definir</div>`;return `<article class="match crossing-card${activeMatchClass(m)}"><div class="line ${m.ganador===m.jugador_1?'winner':''}"><span><strong>${esc(m.numero_1)}</strong> · ${esc(m.jugador_1||'LIBRE')}</span>${setPoints(m,'player_one_points')}</div><div class="line ${m.ganador===m.jugador_2?'winner':''}"><span><strong>${esc(m.numero_2)}</strong> · ${esc(m.jugador_2||'LIBRE')}</span>${setPoints(m,'player_two_points')}</div>${m.horario?`<small>${esc(m.horario)}</small>`:''}${tableStatus(m)}${winner}</article>`}
function crossingGrid(matches){return `<div class="crossing-grid">${matches.slice().sort((a,b)=>a.orden-b.orden).map(crossingCard).join('')}</div>`}
function scheduleMatches(phase,schedule){return phase.partidos.filter(m=>{if(Number(m.ronda)!==Number(schedule.round_number))return false;const from=Number(schedule.from_match||0),to=Number(schedule.to_match||0);return (!from||Number(m.orden)>=from)&&(!to||Number(m.orden)<=to)})}
function remainingMatches(phase){const schedules=phase.horarios_fase||[];const included=new Set(schedules.flatMap(s=>scheduleMatches(phase,s).map(m=>m.id)));return phase.partidos.filter(m=>!included.has(m.id))}
function bracket(phase){return phase.tipo==='slot_elimination'?crossingGrid(phase.partidos):bracketGrid(phase.partidos,phase.clasificados_siguiente_fase)}
function plannedPhase(phase){const schedules=phase.horarios_fase||[],date=s=>s.starts_at?new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'short'}).format(new Date(s.starts_at)):'';return schedules.length?`<div class="schedule-nav">${schedules.map(s=>`<span>${esc(s.name||'Horario a definir')}${date(s)?` · ${esc(date(s))}`:''}</span>`).join('')}</div><div class="empty">Fase programada. Los enfrentamientos se mostrarán cuando queden definidos.</div>`:'<div class="empty">Fase habilitada. Los enfrentamientos y horarios todavía están a definir.</div>'}
function render(index){const phase=data.fases[index];document.querySelectorAll('.tab').forEach((b,i)=>b.classList.toggle('on',i===index));const body=phase.tipo==='zones'?(phase.zonas.length?zones(phase):'<div class="empty">La fase de zonas está habilitada y todavía no tiene zonas definidas.</div>'):(phase.partidos.length?bracket(phase):plannedPhase(phase));document.querySelector('#content').innerHTML=`<section class="panel on"><div class="phase-head"><h2>${esc(phase.nombre)}</h2><span class="badge">${esc(stateLabel(phase.estado))}</span>${sectionActions(phase.nombre,'phase-'+phase.id,phase)}</div>${body}</section>`;document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-slot]').forEach(x=>x.classList.toggle('on',x===b));document.querySelector('#zones').innerHTML=zoneCards(phase,b.dataset.slot)})}
function renderFinal(){document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('on',b.dataset.final==='1'));const rows=data.posiciones_finales||[];const body=rows.length?`<div class="scroll"><table class="standings"><thead><tr><th>Pos</th><th>Jugador</th><th>Club</th><th>Cat</th><th>Instancia</th><th>DS</th><th>Prom</th><th>Pen</th><th>Puntos</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.posicion)}</td><td>${esc(p.jugador)}</td><td>${esc(p.club)}</td><td>${esc(p.categoria)}</td><td>${esc(p.instancia)}</td><td>${esc(p.diferencia_sets)}</td><td>${esc(p.promedio)}</td><td>${esc(p.penalizacion??0)}</td><td><b>${esc(p.puntos??'—')}</b></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Las posiciones finales todavía no están disponibles.</div>';document.querySelector('#content').innerHTML=`<section class="panel on"><div class="phase-head"><h2>Posiciones finales</h2>${sectionActions('Posiciones finales','positions')}</div>${body}</section>`}
let refreshRunning=false,lastPayload='';
function currentViewState(){const phaseButton=document.querySelector('.tab.on[data-i]'),phaseIndex=phaseButton?Number(phaseButton.dataset.i):-1;return {phaseId:phaseIndex>=0&&data?.fases?.[phaseIndex]?Number(data.fases[phaseIndex].id):null,final:document.querySelector('.tab.on[data-final="1"]')!==null,slot:document.querySelector('.slot.on')?.dataset.slot||null}}
function renderNavigation(state={}){const champion=document.querySelector('#champion');champion.classList.toggle('visible',Boolean(data.campeon));champion.innerHTML=data.campeon?`${data.campeon.foto?`<img class="champion-photo" src="${esc(data.campeon.foto)}" alt="${esc(data.campeon.nombre)}">`:''}<div><div class="champion-label">Campeón del torneo</div><div class="champion-name">${esc(data.campeon.nombre)}</div></div>`:'';const phaseTabs=data.fases.map((p,i)=>`<button class="tab" data-i="${i}">${esc(p.nombre)}</button>`).join(''),finalTab=data.mostrar_posiciones_finales?'<button class="tab" data-final="1">Posiciones finales</button>':'';document.querySelector('#tabs').innerHTML=phaseTabs+finalTab;document.querySelector('#tabs').style.display='flex';if(!data.fases.length&&!data.mostrar_posiciones_finales){document.querySelector('#tabs').style.display='none';document.querySelector('#content').innerHTML='<div class="empty">Información no disponible en este momento</div>';return}document.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>render(Number(b.dataset.i)));document.querySelector('[data-final="1"]')?.addEventListener('click',renderFinal);if(state.final&&data.mostrar_posiciones_finales){renderFinal();return}const phaseIndex=Math.max(0,data.fases.findIndex(p=>Number(p.id)===Number(state.phaseId)));if(data.fases.length){render(phaseIndex);if(state.slot){const slotButton=[...document.querySelectorAll('[data-slot]')].find(b=>b.dataset.slot===state.slot);slotButton?.click()}}else{renderFinal()}}
async function refreshPublicResults(initial=false){if(refreshRunning)return;refreshRunning=true;const state=currentViewState();try{const separator=endpoint.includes('?')?'&':'?',response=await fetch(`${endpoint}${separator}_=${Date.now()}`,{cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw new Error('No fue posible obtener los resultados');const payload=await response.json(),signature=JSON.stringify(payload.data);if(signature!==lastPayload){lastPayload=signature;data=payload.data;renderNavigation(state)}}catch(error){if(initial)document.querySelector('#content').innerHTML=`<div class="empty error">${esc(error.message)}</div>`}finally{refreshRunning=false}}
refreshPublicResults(true);
setInterval(()=>{if(!document.hidden)refreshPublicResults()},4000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshPublicResults()});
</script>
</body></html>
